In this lab, we made an Internet of Things (IoT) device that communicates with a temperature sensor over SPI, controls an LED, and serves a web page. The web page lets the user turn the LED on and off and adjust the resolution of the temperature readings. This lab took a total of 25 hours (there were some unexpected delays when a bunch of files were lost).
Below is some code outlining the logic for the temperature sensor, SPI communication, and the behavior of the site when interacting with the ESP module and the temp. sensor.






Notemain.c Logic





    //Defining the web page in two chunks: everything before the current time, and everything after the current time
char* webpageStart = "&lt;!DOCTYPE html&gt;&lt;html&gt;&lt;head&gt;&lt;title&gt;Lab 6 LED & Temp. Control&lt;/title&gt;\
    &lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"&gt;\
    &lt;/head&gt;\
    &lt;body&gt;&lt;h1&gt;Lab 6 LED & Temp. Control&lt;/h1&gt;";
char* ledStr = "&lt;p&gt;LED Control:&lt;/p&gt;&lt;form action=\"ledon\"&gt;&lt;input type=\"submit\" value=\"LED ON\"&gt;&lt;/form&gt;\
    &lt;form action=\"ledoff\"&gt;&lt;input type=\"submit\" value=\"LED OFF\"&gt;&lt;/form&gt;";
char* bitStr = "&lt;p&gt;Bit Resolution Control:&lt;/p&gt;&lt;form action=\"8bit\"&gt;&lt;input type=\"submit\" value=\"8 bits\"&gt;&lt;/form&gt;\
    &lt;form action=\"9bit\"&gt;&lt;input type=\"submit\" value=\"9 bits\"&gt;&lt;/form&gt;\
    &lt;form action=\"10bit\"&gt;&lt;input type=\"submit\" value=\"10 bits\"&gt;&lt;/form&gt;\
    &lt;form action=\"11bit\"&gt;&lt;input type=\"submit\" value=\"11 bits\"&gt;&lt;/form&gt;\
    &lt;form action=\"12bit\"&gt;&lt;input type=\"submit\" value=\"12 bits\"&gt;&lt;/form&gt;";
char* webpageEnd   = "&lt;/body&gt;&lt;/html&gt;";

//determines whether a given character sequence is in a char array request, returning 1 if present, -1 if not present
int inString(char request[], char des[]) {
    if (strstr(request, des) != NULL) {return 1;}
    return -1;
}

int updateLEDStatus(char request[])
{
    int led_status = 0;
    // The request has been received. now process to determine whether to turn the LED on or off
    if (inString(request, "ledoff")==1) {
        digitalWrite(LED_PIN, PIO_LOW);
        led_status = 0;
    }
    else if (inString(request, "ledon")==1) {
        digitalWrite(LED_PIN, PIO_HIGH);
        led_status = 1;
    }

    return led_status;
}

int updateRESStatus(char request[])
{
    int bitresstatus = 0;
    if (inString(request, "8bit")==1) {
        bitresstatus = 8;
                setupDS(0XE0); //sets resolution to 8 bits
    }
    else if (inString(request, "9bit")==1) {
        bitresstatus = 9;
                setupDS(0XE2); //sets resolution to 9 bits
    }
        else if (inString(request, "10bit")==1) {
        bitresstatus = 10;
                setupDS(0XE4); //sets resolution to 10 bits
    }
    else if (inString(request, "11bit")==1) {
        bitresstatus = 11;
                setupDS(0XE6); //sets resolution to 11 bits
    }
        else if (inString(request, "12bit")==1) {
        bitresstatus = 12;
                setupDS(0XE8); //sets resolution to 12 bits
    }
    return bitresstatus;
}

int main(void) {
configureFlash();
configureClock();
gpioEnable(GPIO_PORT_A);
gpioEnable(GPIO_PORT_B);
gpioEnable(GPIO_PORT_C);
pinMode(PB6, GPIO_OUTPUT);
RCC-&gt;APB2ENR |= (RCC_APB2ENR_TIM15EN); //Tim15
initTIM(TIM15);
USART_TypeDef * USART = initUSART(USART1_ID, 125000);
initSPI(0b100, 0, 1); //set clock divider to 2^4, which would be around 500kHz
setupDS(0XE4); // Sets up as 10 bit resolution
volatile uint8_t config;
volatile uint8_t msb;
volatile uint8_t lsb;
volatile uint8_t resolution;
resolution = 10; //using default of 10 bits
while(1) {
    /* Wait for ESP8266 to send a request.
    Requests take the form of '/REQ:&lt;tag&gt;\n', with TAG begin &lt;= 10 characters.
    Therefore the request[] array must be able to contain 18 characters.
    */
    // Receive web request from the ESP
    char request[BUFF_LEN] = "                  "; // initialize to known value
    int charIndex = 0;
    // Keep going until you get end of line character
    while(inString(request, "\n") == -1) {
    // Wait for a complete request to be transmitted before processing
    while(!(USART-&gt;ISR & USART_ISR_RXNE));
    request[charIndex++] = readChar(USART);
}
    config = configread();
    msb = MSBread();
    lsb = LSBread();
    int led_status = updateLEDStatus(request); //get LED data
    resolution = updateRESStatus(request); //get resolution data
    float temp = numtotemp(msb,  lsb);
    char tempStr[50];
    sprintf(tempStr,"Temperature is %.4f degrees C",temp);
    char resStr[50];
    sprintf(resStr,"Resolution is %d bits",resolution);
    char ledStatusStr[20];
    if (led_status == 1)
    sprintf(ledStatusStr,"LED ON");
    else if (led_status == 0)
    sprintf(ledStatusStr,"LED OFF");
    //// finally, transmit the webpage over UART
    sendString(USART, webpageStart); // webpage header code
    sendString(USART, ledStr); // LED buttons
    sendString(USART, bitStr); // resolution buttons
    sendString(USART, "&lt;p&gt;");
    sendString(USART, ledStatusStr); //LED is on or off?
    sendString(USART, "&lt;/p&gt;");
    sendString(USART, "&lt;h2&gt;Temperature&lt;/h2&gt;");
    sendString(USART, "&lt;p&gt;");
    sendString(USART, tempStr); //what is the current temperature?
    sendString(USART, "&lt;/p&gt;");
    sendString(USART, "&lt;h2&gt;Resolution&lt;/h2&gt;");
    sendString(USART, "&lt;p&gt;");
    sendString(USART, resStr); //what is the current resolution?
    sendString(USART, "&lt;/p&gt;");
    sendString(USART, webpageEnd);//end
}
}

